        monkeypatch.delenv("LOG_LEVEL", raising=False)
    else:
        monkeypatch.setenv("LOG_LEVEL", level)
    r = _two_tool_run()
    assert capsys.readouterr() == ("", "")
    assert r.reply == "ok" and len(r.tool_calls) == 2


